/// <summary>
/// Метод удаления ордера для Binance
/// </summary>
public class RMarketMethod_Binance_CancelOrder extends RMarketMethod implements RMarketMethodInterface_CancelOrder
{
    protected RMarketJson_Binance_CancelOrder responseContract;
    protected str symbol;
    protected str orderId;

}

Method.Source:
/// <summary> Конструктор класса </summary>
public void new()
{
    apiClient = new RMarketApiClientBinance();
    apiClient.parmHttpMethod(RMarketAPIHttpMethod::DELETE);
    apiClient.parmMethodUrl('/api/v3/order');

    // Do this before execute()
    //apiClient.setBaseUrl(URL _baseUrl);
    //apiClient.setApiKey(RMarketApiKey _apiKey)
}

/// <summary> Удалить ордер на Binance </summary>
/// <param name="_symbol"> Торговый символ </param>
/// <param name="_orderId"> ID ордера </param>
/// <returns> Результат удаления ордера </returns>
public void initParameters(
    RMarketType _marketType,
    RMarketSymbolId _symbol,
    str _orderId)
{
    //symbol	            STRING	YES
    //orderId	            LONG	NO
    //origClientOrderId	    STRING	NO
    //newClientOrderId	    STRING	NO	Used to uniquely identify this cancel. Automatically generated by default.
    //cancelRestrictions	ENUM	NO	Supported values:
    //                                ONLY_NEW - Cancel will succeed if the order status is NEW.
    //                                ONLY_PARTIALLY_FILLED - Cancel will succeed if order status is PARTIALLY_FILLED.
    //recvWindow	        LONG	NO	The value cannot be greater than 60000.
    //timestamp	            LONG	YES

    //Notes:
    //Either orderId or origClientOrderId must be sent.
    //If both orderId and origClientOrderId are provided, the orderId is searched first, then the origClientOrderId from that result is checked against that order. If both conditions are not met the request will be rejected.
    symbol = _symbol;
    orderId = _orderId;

    apiClient.addQueryParam("symbol", symbol);
    apiClient.addQueryParam('orderId', orderId);
}

public void processResponse()
{
    super();

    str responseStr = apiClient.getResponseBody();

    if (apiClient.getHttpStatus() != System.Net.HttpStatusCode::OK)
        throw Error(strfmt("Request returns error!"));

    responseContract = RMarketJsonSerializer::deserializeObject(
        classNum(RMarketJson_Binance_CancelOrder),
        responseStr) as RMarketJson_Binance_CancelOrder;
}
